using Dapper;
using Microsoft.Extensions.Configuration;
using MySqlConnector;
using ReadBookRepo.Publishing;

namespace ReadBookRepo.PersonalReading;

public sealed class PersonalReadingRepository(IConfiguration configuration):IPersonalReadingRepository
{
    private readonly string _cs=configuration.GetConnectionString("Default")??throw new InvalidOperationException("ConnectionStrings:Default is not configured.");
    private async Task EnsureActive(MySqlConnection c,Guid userId,CancellationToken ct){await using var check=new MySqlConnection(_cs);if(!await check.ExecuteScalarAsync<bool>(new CommandDefinition("SELECT EXISTS(SELECT 1 FROM `user` WHERE user_id=@userId AND status=1)",new{userId},cancellationToken:ct)))throw new PublishingException(403,"Tài khoản không hoạt động.");}
    private static async Task EnsureReadable(MySqlConnection c,Guid novelId,Guid chapterId,CancellationToken ct,MySqlTransaction? tx=null){if(!await c.ExecuteScalarAsync<bool>(new CommandDefinition("SELECT EXISTS(SELECT 1 FROM chapter c JOIN novel n ON n.novel_id=c.novel_id WHERE c.chapter_id=@chapterId AND c.novel_id=@novelId AND c.review_status=1 AND c.visibility=0 AND c.deleted_at IS NULL AND n.review_status=1 AND n.visibility=0 AND n.deleted_at IS NULL)",new{novelId,chapterId},tx,cancellationToken:ct)))throw new PublishingException(404,"Truyện hoặc chương không thể đọc công khai.");}
    public async Task SaveAsync(Guid userId,Guid novelId,CancellationToken ct=default){await using var c=new MySqlConnection(_cs);await c.OpenAsync(ct);await EnsureActive(c,userId,ct);var ok=await c.ExecuteScalarAsync<bool>(new CommandDefinition("SELECT EXISTS(SELECT 1 FROM novel WHERE novel_id=@novelId AND review_status=1 AND visibility=0 AND deleted_at IS NULL)",new{novelId},cancellationToken:ct));if(!ok)throw new PublishingException(404,"Không tìm thấy truyện công khai.");await c.ExecuteAsync(new CommandDefinition("INSERT IGNORE INTO library_item(user_id,novel_id) VALUES(@userId,@novelId)",new{userId,novelId},cancellationToken:ct));}
    public async Task RemoveAsync(Guid userId,Guid novelId,CancellationToken ct=default){await using var c=new MySqlConnection(_cs);await c.OpenAsync(ct);await EnsureActive(c,userId,ct);await c.ExecuteAsync(new CommandDefinition("DELETE FROM library_item WHERE user_id=@userId AND novel_id=@novelId",new{userId,novelId},cancellationToken:ct));}
    public async Task<PagedLibrary> ListAsync(Guid userId,int page,int pageSize,string sort,CancellationToken ct=default){page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,50);var order=sort.ToLowerInvariant() switch{"title"=>"n.title ASC","updated"=>"n.updated_at DESC",_=>"li.created_at DESC"};await using var c=new MySqlConnection(_cs);await c.OpenAsync(ct);await EnsureActive(c,userId,ct);var total=await c.ExecuteScalarAsync<long>(new CommandDefinition("SELECT COUNT(*) FROM library_item WHERE user_id=@userId",new{userId},cancellationToken:ct));var sql=$"SELECT n.novel_id NovelId,n.title Title,n.cover_url CoverUrl,n.original_author OriginalAuthor,n.description Description,n.completion_status CompletionStatus,li.created_at SavedAt,n.updated_at UpdatedAt FROM library_item li JOIN novel n ON n.novel_id=li.novel_id WHERE li.user_id=@userId ORDER BY {order} LIMIT @offset,@pageSize";var items=(await c.QueryAsync<LibraryNovel>(new CommandDefinition(sql,new{userId,offset=(page-1)*pageSize,pageSize},cancellationToken:ct))).AsList();return new(items,page,pageSize,total);}
    public async Task<ReadSessionResult> BeginAsync(Guid userId,Guid novelId,Guid chapterId,CancellationToken ct=default)
    {
        await using var c=new MySqlConnection(_cs);await c.OpenAsync(ct);await EnsureActive(c,userId,ct);
        await using var tx=await c.BeginTransactionAsync(ct);await EnsureReadable(c,novelId,chapterId,ct,tx);
        var id=Guid.NewGuid();var now=DateTime.UtcNow;
        await c.ExecuteAsync(new CommandDefinition("INSERT INTO reading_session(session_id,user_id,novel_id,started_at) VALUES(@id,@userId,@novelId,@now); INSERT INTO reading_history(user_id,chapter_id,read_at) VALUES(@userId,@chapterId,@now)",new{id,userId,novelId,chapterId,now},tx,cancellationToken:ct));
        await tx.CommitAsync(ct);return new(id,now);
    }
    public async Task<ReadingProgressResult> UpdateProgressAsync(Guid userId,Guid novelId,Guid chapterId,ProgressRequest r,CancellationToken ct=default){if(r.PositionPercent<0||r.PositionPercent>100||r.Sequence<0)throw new PublishingException(400,"Tiến độ phải từ 0 đến 100 và sequence không âm.");await using var c=new MySqlConnection(_cs);await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);await EnsureActive(c,userId,ct);await EnsureReadable(c,novelId,chapterId,ct,tx);var session=await c.QuerySingleOrDefaultAsync<DateTime?>(new CommandDefinition("SELECT started_at FROM reading_session WHERE session_id=@SessionId AND user_id=@userId AND novel_id=@novelId",new{r.SessionId,userId,novelId},tx,cancellationToken:ct));if(session is null)throw new PublishingException(409,"Read session không hợp lệ.");var changed=await c.ExecuteAsync(new CommandDefinition("INSERT INTO reading_progress(user_id,novel_id,chapter_id,position_percent,session_id,session_started_at,client_sequence) VALUES(@userId,@novelId,@chapterId,@PositionPercent,@SessionId,@started,@Sequence) ON DUPLICATE KEY UPDATE chapter_id=IF(VALUES(session_started_at)>session_started_at OR (VALUES(session_started_at)=session_started_at AND VALUES(client_sequence)>client_sequence),VALUES(chapter_id),chapter_id),position_percent=IF(VALUES(session_started_at)>session_started_at OR (VALUES(session_started_at)=session_started_at AND VALUES(client_sequence)>client_sequence),VALUES(position_percent),position_percent),session_id=IF(VALUES(session_started_at)>session_started_at OR (VALUES(session_started_at)=session_started_at AND VALUES(client_sequence)>client_sequence),VALUES(session_id),session_id),client_sequence=GREATEST(client_sequence,IF(VALUES(session_started_at)=session_started_at,VALUES(client_sequence),client_sequence)),session_started_at=GREATEST(session_started_at,VALUES(session_started_at)),updated_at=IF(VALUES(session_started_at)>session_started_at OR (VALUES(session_started_at)=session_started_at AND VALUES(client_sequence)>client_sequence),CURRENT_TIMESTAMP,updated_at)",new{userId,novelId,chapterId,r.PositionPercent,r.SessionId,started=session.Value,r.Sequence},tx,cancellationToken:ct));await c.ExecuteAsync(new CommandDefinition("INSERT INTO reading_history(user_id,chapter_id) VALUES(@userId,@chapterId)",new{userId,chapterId},tx,cancellationToken:ct));await tx.CommitAsync(ct);return (await ContinueAsync(userId,novelId,ct))!;}
    public async Task<ReadingProgressResult?> ContinueAsync(Guid userId,Guid novelId,CancellationToken ct=default){await using var c=new MySqlConnection(_cs);await c.OpenAsync(ct);await EnsureActive(c,userId,ct);const string sql="SELECT rp.novel_id NovelId,rp.chapter_id ChapterId,c.chapter_number ChapterNumber,c.title ChapterTitle,rp.position_percent PositionPercent,rp.updated_at UpdatedAt,(c.review_status=1 AND c.visibility=0 AND c.deleted_at IS NULL AND n.review_status=1 AND n.visibility=0 AND n.deleted_at IS NULL) Available FROM reading_progress rp JOIN chapter c ON c.chapter_id=rp.chapter_id JOIN novel n ON n.novel_id=rp.novel_id WHERE rp.user_id=@userId AND rp.novel_id=@novelId";return await c.QuerySingleOrDefaultAsync<ReadingProgressResult>(new CommandDefinition(sql,new{userId,novelId},cancellationToken:ct));}
    public async Task<ViewResult> RecordViewAsync(Guid userId,Guid novelId,Guid chapterId,int windowMinutes,CancellationToken ct=default){windowMinutes=Math.Clamp(windowMinutes,1,1440);await using var c=new MySqlConnection(_cs);await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);await EnsureActive(c,userId,ct);await EnsureReadable(c,novelId,chapterId,ct,tx);var bucket=DateTime.UtcNow.Ticks/(TimeSpan.TicksPerMinute*windowMinutes);var n=await c.ExecuteAsync(new CommandDefinition("INSERT IGNORE INTO chapter_view(chapter_id,user_id,view_window) VALUES(@chapterId,@userId,@bucket)",new{chapterId,userId,bucket},tx,cancellationToken:ct));await tx.CommitAsync(ct);return new(n==1,windowMinutes);}

    async Task<ReadingProgressResult> IPersonalReadingRepository.UpdateProgressAsync(Guid userId,Guid novelId,Guid chapterId,ProgressRequest r,CancellationToken ct)
    {
        if(r.PositionPercent<0||r.PositionPercent>100||r.Sequence<0)throw new PublishingException(400,"Tiến độ phải từ 0 đến 100 và sequence không âm.");
        await using var c=new MySqlConnection(_cs);await c.OpenAsync(ct);await EnsureActive(c,userId,ct);
        await using var tx=await c.BeginTransactionAsync(ct);await EnsureReadable(c,novelId,chapterId,ct,tx);
        var started=await c.QuerySingleOrDefaultAsync<DateTime?>(new CommandDefinition("SELECT started_at FROM reading_session WHERE session_id=@SessionId AND user_id=@userId AND novel_id=@novelId",new{r.SessionId,userId,novelId},tx,cancellationToken:ct));
        if(started is null)throw new PublishingException(409,"Read session không hợp lệ.");
        const string sql="INSERT INTO reading_progress(user_id,novel_id,chapter_id,position_percent,session_id,session_started_at,client_sequence) VALUES(@userId,@novelId,@chapterId,@PositionPercent,@SessionId,@started,@Sequence) ON DUPLICATE KEY UPDATE chapter_id=IF(VALUES(session_started_at)>session_started_at OR (VALUES(session_started_at)=session_started_at AND VALUES(client_sequence)>client_sequence),VALUES(chapter_id),chapter_id),position_percent=IF(VALUES(session_started_at)>session_started_at OR (VALUES(session_started_at)=session_started_at AND VALUES(client_sequence)>client_sequence),VALUES(position_percent),position_percent),session_id=IF(VALUES(session_started_at)>session_started_at OR (VALUES(session_started_at)=session_started_at AND VALUES(client_sequence)>client_sequence),VALUES(session_id),session_id),client_sequence=GREATEST(client_sequence,IF(VALUES(session_started_at)=session_started_at,VALUES(client_sequence),client_sequence)),session_started_at=GREATEST(session_started_at,VALUES(session_started_at)),updated_at=IF(VALUES(session_started_at)>session_started_at OR (VALUES(session_started_at)=session_started_at AND VALUES(client_sequence)>client_sequence),CURRENT_TIMESTAMP,updated_at)";
        await c.ExecuteAsync(new CommandDefinition(sql,new{userId,novelId,chapterId,r.PositionPercent,r.SessionId,started=started.Value,r.Sequence},tx,cancellationToken:ct));
        await tx.CommitAsync(ct);return(await ContinueAsync(userId,novelId,ct))!;
    }

    public async Task<PagedHistory> HistoryAsync(Guid userId,int page,int pageSize,CancellationToken ct=default)
    {
        page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,50);await using var c=new MySqlConnection(_cs);await c.OpenAsync(ct);await EnsureActive(c,userId,ct);
        var total=await c.ExecuteScalarAsync<long>(new CommandDefinition("SELECT COUNT(*) FROM reading_history WHERE user_id=@userId",new{userId},cancellationToken:ct));
        const string sql="SELECT h.history_id HistoryId,n.novel_id NovelId,n.title NovelTitle,c.chapter_id ChapterId,c.chapter_number ChapterNumber,c.title ChapterTitle,h.read_at ReadAt,(c.review_status=1 AND c.visibility=0 AND c.deleted_at IS NULL AND n.review_status=1 AND n.visibility=0 AND n.deleted_at IS NULL) Available FROM reading_history h JOIN chapter c ON c.chapter_id=h.chapter_id JOIN novel n ON n.novel_id=c.novel_id WHERE h.user_id=@userId ORDER BY h.read_at DESC,h.history_id DESC LIMIT @offset,@pageSize";
        var items=(await c.QueryAsync<HistoryItem>(new CommandDefinition(sql,new{userId,offset=(page-1)*pageSize,pageSize},cancellationToken:ct))).AsList();return new(items,page,pageSize,total);
    }
}
